/* eslint-disable */
// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading — delayRender/continueRender handled internally
const { fontFamily: interFamily } = loadInter();



export type YearFlipProps = Record<string, any>;

const YearFlip: React.FC<YearFlipProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = false,
  durationInSeconds = 5,
  textColor = "#ffffff",
  prefix = "20",
  startSuffix = 14,
  endSuffix = 24,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Handle transparent backgrounds
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive layout calculations tailored for 9:16 vertical stack presence
  const shortestSide = Math.min(width, height);
  const casingWidth = shortestSide * 0.9;
  const casingHeight = casingWidth * 0.6;
  const cardBorderRadius = shortestSide * 0.05; // Slightly rounder for iOS Liquid Glass feel
  const fontSize = casingHeight * 0.55;

  // Generate the array of numbers to flip through
  const items: number[] = [];
  const direction = startSuffix <= endSuffix ? 1 : -1;
  const count = Math.abs(endSuffix - startSuffix) + 1;
  
  for (let i = 0; i < count; i++) {
    items.push(startSuffix + i * direction);
  }

  // Animation Timings
  const totalFrames = durationInSeconds * fps;
  const holdStartFrames = Math.min(fps * 0.8, totalFrames * 0.2);
  const holdEndFrames = Math.min(fps * 1.5, totalFrames * 0.4);
  const rollDurationFrames = Math.max(1, totalFrames - holdStartFrames - holdEndFrames);
  const rollEndFrame = holdStartFrames + rollDurationFrames;

  // Physical split-flap roll progress (0 to max index)
  const rollProgress = interpolate(
    frame,
    [holdStartFrames, rollEndFrame],
    [0, count - 1],
    {
      easing: Easing.inOut(Easing.exp),
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // Calculate strict flap indices and fractional flip progress
  const safeProgress = Math.min(count - 1, Math.max(0, rollProgress));
  const currentIndex = Math.min(count - 2, Math.floor(safeProgress));
  const fraction = safeProgress - currentIndex;

  const currentSuffix = items[currentIndex].toString().padStart(2, "0");
  const nextSuffix = items[currentIndex + 1].toString().padStart(2, "0");

  // Subtle continuous cinematic zoom
  const globalScale = interpolate(frame, [0, totalFrames], [0.95, 1.05], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Dynamic Liquid Orbs for ambient refraction (pure math, no random)
  const orb1X = interpolate(Math.sin(frame / 40), [-1, 1], [-60, 60]);
  const orb1Y = interpolate(Math.cos(frame / 30), [-1, 1], [-60, 60]);
  
  const orb2X = interpolate(Math.cos(frame / 35), [-1, 1], [-80, 80]);
  const orb2Y = interpolate(Math.sin(frame / 45), [-1, 1], [-80, 80]);

  const orb3X = interpolate(Math.sin(frame / 50), [-1, 1], [-50, 50]);
  const orb3Y = interpolate(Math.cos(frame / 40), [-1, 1], [-50, 50]);

  // Shared Glass Styles
  const cardBaseStyle: React.CSSProperties = {
    flex: 1,
    height: '100%',
    background: 'transparent',
    borderRadius: cardBorderRadius,
    position: 'relative',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    perspective: '1500px', // Crucial for 3D split-flap effect
    zIndex: 2,
  };

  const textStyle: React.CSSProperties = {
    position: 'absolute',
    width: '100%',
    height: '100%',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    fontSize,
    color: textColor,
    fontWeight: 900,
    fontVariantNumeric: "tabular-nums",
    letterSpacing: "-0.05em",
    lineHeight: 1,
    borderRadius: cardBorderRadius,
    
    // Liquid Glass UI Flap Styles
    background: 'linear-gradient(135deg, rgba(255,255,255,0.15) 0%, rgba(255,255,255,0.02) 100%)',
    backdropFilter: 'blur(20px)',
    WebkitBackdropFilter: 'blur(20px)',
    boxShadow: 'inset 0 1px 1px rgba(255,255,255,0.4), 0 8px 32px rgba(0,0,0,0.2)',
    border: '1px solid rgba(255,255,255,0.15)',
    borderTop: '1px solid rgba(255,255,255,0.3)',
    backfaceVisibility: 'hidden',
    textShadow: '0 4px 15px rgba(0,0,0,0.2)',
  };

  const casingGloss = (
    <div style={{
      position: 'absolute',
      top: 0, left: 0, right: 0, height: '40%',
      background: 'linear-gradient(180deg, rgba(255,255,255,0.1) 0%, rgba(255,255,255,0) 100%)',
      borderRadius: `${cardBorderRadius * 1.5}px ${cardBorderRadius * 1.5}px 0 0`,
      pointerEvents: 'none',
      zIndex: 10,
    }} />
  );

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        fontFamily: interFamily,
        transition: "none",
        overflow: "hidden",
      }}
    >
      {/* Ambient Liquid Orbs for Refraction */}
      {!transparentBackground && (
        <div style={{ position: 'absolute', width: '100%', height: '100%', pointerEvents: 'none' }}>
          <div style={{
            position: 'absolute', top: '20%', left: '15%',
            width: shortestSide * 0.7, height: shortestSide * 0.7,
            backgroundColor: '#ff2a5f', borderRadius: '50%',
            filter: 'blur(120px)', opacity: 0.45,
            transform: `translate(${orb1X}px, ${orb1Y}px)`,
          }} />
          <div style={{
            position: 'absolute', bottom: '15%', right: '15%',
            width: shortestSide * 0.8, height: shortestSide * 0.8,
            backgroundColor: '#00d2ff', borderRadius: '50%',
            filter: 'blur(140px)', opacity: 0.45,
            transform: `translate(${orb2X}px, ${orb2Y}px)`,
          }} />
          <div style={{
            position: 'absolute', top: '40%', left: '40%',
            width: shortestSide * 0.6, height: shortestSide * 0.6,
            backgroundColor: '#7b2cbf', borderRadius: '50%',
            filter: 'blur(100px)', opacity: 0.35,
            transform: `translate(${orb3X}px, ${orb3Y}px)`,
          }} />
        </div>
      )}

      <div style={{ transform: `scale(${globalScale})`, transition: "none", display: 'flex' }}>
        
        {/* Outer Liquid Glass Casing */}
        <div style={{
          position: 'relative',
          width: casingWidth,
          height: casingHeight,
          background: 'linear-gradient(135deg, rgba(255,255,255,0.1) 0%, rgba(255,255,255,0.02) 100%)',
          backdropFilter: 'blur(40px)',
          WebkitBackdropFilter: 'blur(40px)',
          border: '1px solid rgba(255,255,255,0.2)',
          borderTop: '1px solid rgba(255,255,255,0.4)',
          borderRadius: cardBorderRadius * 1.5,
          padding: '4%',
          display: 'flex',
          gap: '4%',
          boxShadow: '0 30px 60px rgba(0,0,0,0.4), inset 0 1px 20px rgba(255,255,255,0.1)',
        }}>
          
          {casingGloss}

          {/* Prefix Card (Static Glass) */}
          <div style={cardBaseStyle}>
            <div style={textStyle}>
              {prefix}
            </div>
          </div>

          {/* Suffix Card (Animated 3D Glass Split Flap) */}
          <div style={cardBaseStyle}>
            
            {/* Base Top Half (Reveals Next Number) */}
            <div style={{ ...textStyle, clipPath: 'inset(0 0 50% 0)' }}>
              {/* Only reveal next text when flap starts lifting to eliminate bleed-through at rest */}
              <span style={{ opacity: Math.min(1, fraction * 20) }}>
                {nextSuffix}
              </span>
            </div>

            {/* Base Bottom Half (Holds Current Number) */}
            <div style={{ ...textStyle, clipPath: 'inset(50% 0 0 0)' }}>
              {/* Hide current text when the next flap has fully landed on it */}
              <span style={{ opacity: Math.min(1, (1 - fraction) * 20) }}>
                {currentSuffix}
              </span>
            </div>

            {/* Flap 1: Top half swinging down (Shows Current Number) */}
            {fraction < 0.5 && (
              <div style={{
                ...textStyle,
                clipPath: 'inset(0 0 50% 0)',
                transformOrigin: 'center center',
                transform: `rotateX(${fraction * -180}deg)`,
                zIndex: 5,
                // Soft shadow for glass instead of hard black
                filter: `brightness(${1 - fraction * 0.3})`
              }}>
                {currentSuffix}
              </div>
            )}

            {/* Flap 2: Bottom half landing (Shows Next Number) */}
            {fraction >= 0.5 && (
              <div style={{
                ...textStyle,
                clipPath: 'inset(50% 0 0 0)',
                transformOrigin: 'center center',
                transform: `rotateX(${90 - ((fraction - 0.5) * 180)}deg)`,
                zIndex: 5,
                // Catching light as it lands
                filter: `brightness(${0.8 + (fraction - 0.5) * 0.4})`
              }}>
                {nextSuffix}
              </div>
            )}
          </div>

        </div>
      </div>
    </AbsoluteFill>
  );
};

export default YearFlip;